	StartWebAuthnRegistration(context.Context, *StartWebAuthnRegistrationRequest) (*StartWebAuthnRegistrationResponse, error)
	FinishWebAuthnRegistration(context.Context, *FinishWebAuthnRegistrationRequest) (*FinishWebAuthnRegistrationResponse, error)
	StartWebAuthnAuthentication(context.Context, *StartWebAuthnAuthenticationRequest) (*StartWebAuthnAuthenticationResponse, error)
	FinishWebAuthnAuthentication(context.Context, *FinishWebAuthnAuthenticationRequest) (*FinishWebAuthnAuthenticationResponse, error)
	// ── Device + session revocation lifecycle (Phase 3 / I2.4) ───────────────
	ListDevices(context.Context, *ListDevicesRequest) (*ListDevicesResponse, error)
	RevokeDevice(context.Context, *RevokeDeviceRequest) (*RevokeDeviceResponse, error)
	AdminRevokeSession(context.Context, *AdminRevokeSessionRequest) (*AdminRevokeSessionResponse, error)
	AdminRevokeAllUserSessions(context.Context, *AdminRevokeAllUserSessionsRequest) (*AdminRevokeAllUserSessionsResponse, error)
	AdminRevokeAllTenantSessions(context.Context, *AdminRevokeAllTenantSessionsRequest) (*AdminRevokeAllTenantSessionsResponse, error)
	EmergencyRevoke(context.Context, *EmergencyRevokeRequest) (*EmergencyRevokeResponse, error)
	// ── MFA challenge + factor lifecycle (Phase 3 / I2.6) ────────────────────
	IssueMfaChallenge(context.Context, *IssueMfaChallengeRequest) (*IssueMfaChallengeResponse, error)
	VerifyMfaChallenge(context.Context, *VerifyMfaChallengeRequest) (*VerifyMfaChallengeResponse, error)
	ListMfaFactors(context.Context, *ListMfaFactorsRequest) (*ListMfaFactorsResponse, error)
	DisableMfaFactor(context.Context, *DisableMfaFactorRequest) (*DisableMfaFactorResponse, error)
	RenamePasskey(context.Context, *RenamePasskeyRequest) (*RenamePasskeyResponse, error)
	RevokeRecoveryCodes(context.Context, *RevokeRecoveryCodesRequest) (*RevokeRecoveryCodesResponse, error)
	AdminResetMfa(context.Context, *AdminResetMfaRequest) (*AdminResetMfaResponse, error)
	// ── WebAuthn enterprise credential lifecycle (Phase 3 / I2.7) ────────────
	ListWebAuthnCredentials(context.Context, *ListWebAuthnCredentialsRequest) (*ListWebAuthnCredentialsResponse, error)
	DeleteWebAuthnCredential(context.Context, *DeleteWebAuthnCredentialRequest) (*DeleteWebAuthnCredentialResponse, error)
	// ── Typed service-account grants + mTLS certificate bindings (UDB-AUTH-003/007) ──
	// Create the single typed grant for a service account: immutable service
	// identity, tenant/project binding, and operator-approved scopes.
	// Admin/owner/wildcard scopes are rejected at write time (fail closed).
	CreateServiceAccountGrant(context.Context, *CreateServiceAccountGrantRequest) (*CreateServiceAccountGrantResponse, error)
	// Read the current typed grant for a service account; NOT_FOUND when the
	// account has no grant (the account then cannot authenticate — fail closed).
	GetServiceAccountGrant(context.Context, *GetServiceAccountGrantRequest) (*GetServiceAccountGrantResponse, error)
	// Page through the tenant's typed service-account grants (tenant-scoped;
	// cross-tenant reads are rejected).
	ListServiceAccountGrants(context.Context, *ListServiceAccountGrantsRequest) (*ListServiceAccountGrantsResponse, error)
	// Replace a grant's approved scopes/project atomically, bumping `revision` so
	// dependent credentials and bindings detect staleness. A stale
	// expected_revision fails with FAILED_PRECONDITION (fail closed).
	ReplaceServiceAccountGrant(context.Context, *ReplaceServiceAccountGrantRequest) (*ReplaceServiceAccountGrantResponse, error)
	// Rotate the immutable service identity through an explicit audited CAS.
	// The revision bump invalidates all API keys and certificate bindings
	// reviewed against the prior identity; already-issued service JWTs fail the
	// current-grant identity check immediately.
	RotateServiceAccountIdentity(context.Context, *RotateServiceAccountIdentityRequest) (*RotateServiceAccountIdentityResponse, error)
	// Atomically transfer an ACTIVE service-account grant (its stable
	// service_identity and approved scopes) from one service account to another,
	// under revision CAS. The grant row is re-pointed from `from_user_id` to
	// `to_user_id` in a single transaction, so neither the deployment-wide
	// service_identity unique index nor the per-user unique index is ever
	// violated, and no window exists in which no account owns the identity. The
	// source account is left with no grant (its credentials no longer resolve to
	// the identity); the move is a deterministic inverse of itself. This is the
	// supported recovery path when the currently-bound account's credentials are
	// unavailable, replacing a non-atomic rotate-then-create.
	TransferServiceAccountGrant(context.Context, *TransferServiceAccountGrantRequest) (*TransferServiceAccountGrantResponse, error)
